import Model from 'flarum/common/Model';
/** A calendar event series (`calendar-events`), as the store keeps it. api.ts turns it into the plain CalEvent the views use. */
export default class CalendarEvent extends Model {
  title = Model.attribute('title');
  slug = Model.attribute('slug');
  description = Model.attribute('description');
  start = Model.attribute('start');
  end = Model.attribute('end');
  allDay = Model.attribute('allDay');
  timezone = Model.attribute('timezone');
  location = Model.attribute('location');
  url = Model.attribute('url');
  coverUrl = Model.attribute('coverUrl');
  rrule = Model.attribute('rrule');
  categoryId = Model.attribute('categoryId');
  recurring = Model.attribute('recurring');
  isPublished = Model.attribute('isPublished');
  discussionId = Model.attribute('discussionId');
  canEdit = Model.attribute('canEdit');
  icalUrl = Model.attribute('icalUrl');
  googleUrl = Model.attribute('googleUrl');
  /** Only on list responses: each occurrence inside the requested window. */
  occurrences = Model.attribute('occurrences');
  rsvp = Model.attribute('rsvp');
  user = Model.hasOne('user');
  category = Model.hasOne('category');
}
flarum.reg.add('ernestdefoe-calendar', 'common/models/CalendarEvent', CalendarEvent);