import app from 'flarum/common/app';
import { invalidate } from './widgetData';

/** An event as the views use it: one occurrence of a calendar-events resource (EventResource). */

const api = path => app.forum.attribute('apiUrl') + path;
export const base = () => app.forum.attribute('baseUrl');

/** A store model's attributes, copied, so the views get the same plain object the resource sent. */
const attrsOf = model => ({
  ...(model.data.attributes || {})
});
const toCategory = model => ({
  ...attrsOf(model),
  id: Number(model.id())
});

/** Turn one calendar-events model into the CalEvent the views use. */
function toEvent(model) {
  const {
    occurrences,
    ...attrs
  } = attrsOf(model);
  const user = model.user();
  const category = model.category();
  return {
    ...attrs,
    id: Number(model.id()),
    occurrence: null,
    category: category ? toCategory(category) : null,
    author: user ? {
      id: Number(user.id()),
      username: user.attribute('username'),
      displayName: user.attribute('displayName'),
      avatarUrl: user.attribute('avatarUrl')
    } : null
  };
}

/** A listed series becomes one CalEvent per occurrence inside the window, sorted by start. */
function toOccurrences(models) {
  const events = [];
  models.forEach(model => {
    const event = toEvent(model);
    (model.occurrences() || []).forEach(o => {
      events.push({
        ...event,
        occurrence: o.occurrence,
        start: o.start,
        end: o.end,
        googleUrl: o.googleUrl
      });
    });
  });
  return events.sort((a, b) => a.start.localeCompare(b.start));
}

/** The store's copy of a record we only know by id (pushed as existing, so save() PATCHes and delete() DELETEs). */
function known(type, id) {
  return app.store.getById(type, String(id)) ?? app.store.pushObject({
    type,
    id: String(id),
    attributes: {}
  });
}
const widget = (name, query = {}) => {
  const qs = new URLSearchParams();
  Object.entries(query).forEach(([k, v]) => {
    if (v !== undefined) qs.set('filter[' + k + ']', String(v));
  });
  const s = qs.toString();
  return app.request({
    method: 'GET',
    url: api('/calendar-widgets/' + name + (s ? '?' + s : ''))
  }).then(r => r.data);
};
export function onThisDay(limit = 6) {
  return widget('memories', {
    limit
  });
}
export function celebrations() {
  return widget('celebrations');
}

/** Absolute URL for a server path the API handed us (e.g. an .ics path). */
export const abs = path => base().replace(/\/$/, '') + '/' + path.replace(/^\//, '');
export const feedUrl = () => abs('calendar/feed.ics');
export function userActivity(userId) {
  return widget('activity', {
    user: userId
  });
}
export function forumPulse(opts = {}) {
  return widget('pulse', opts);
}
export function listEvents(from, to, category) {
  const filter = {
    from: from.toISOString(),
    to: to.toISOString()
  };
  if (category) filter.category = category;

  // The store passes the filter as request params, which Mithril encodes — so the ':' in the ISO dates is safe.
  return Promise.all([app.store.find('calendar-events', {
    filter
  }), listCategories()]).then(([models, categories]) => ({
    data: toOccurrences(models),
    categories
  }));
}
export function showEvent(id) {
  return app.store.find('calendar-events', String(id)).then(toEvent);
}
export function saveEvent(attrs, id) {
  const model = id ? known('calendar-events', id) : app.store.createRecord('calendar-events');
  return model.save(attrs).then(saved => {
    invalidate('events:');
    return toEvent(saved);
  });
}

/** POST to one of an event's own endpoints (rsvp, discussion) and store the event it answers with. */
function eventAction(id, action, body) {
  return app.request({
    method: 'POST',
    url: api('/calendar-events/' + id + '/' + action),
    ...(body ? {
      body
    } : {})
  }).then(payload => {
    invalidate('events:');
    return app.store.pushPayload(payload);
  });
}

/** Start the comment thread for an event that has none. */
export function startDiscussion(id) {
  return eventAction(id, 'discussion').then(toEvent);
}
export function deleteEvent(id) {
  return known('calendar-events', id).delete().then(r => {
    invalidate('events:');
    return r;
  });
}
export function rsvp(id, status) {
  return eventAction(id, 'rsvp', {
    data: {
      attributes: {
        status
      }
    }
  }).then(model => model.rsvp());
}
export function listCategories() {
  return app.store.find('calendar-categories').then(models => models.map(toCategory));
}
export function saveCategory(attrs, id) {
  const model = id ? known('calendar-categories', id) : app.store.createRecord('calendar-categories');
  return model.save(attrs).then(toCategory);
}
export function deleteCategory(id) {
  return known('calendar-categories', id).delete();
}
flarum.reg.add('ernestdefoe-calendar', 'common/api', { base: base,onThisDay: onThisDay,celebrations: celebrations,abs: abs,feedUrl: feedUrl,userActivity: userActivity,forumPulse: forumPulse,listEvents: listEvents,showEvent: showEvent,saveEvent: saveEvent,startDiscussion: startDiscussion,deleteEvent: deleteEvent,rsvp: rsvp,listCategories: listCategories,saveCategory: saveCategory,deleteCategory: deleteCategory, });